t"}, {"id": "78a54d9d-c273-468e-bdbe-46616bf49453", "type": "concept", "title": "Reflection on contemporary relevance and limitations"}], "description": "Students demonstrate mastery through a polished written and visual presentation that communicates to an informed audience."}]}], "dbBacked": true}$mocajson$::jsonb,
