values
  ('4eefcc1b-fd75-4b7d-85a3-76234366604a', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', null, 'topic'::public.curated_course_node_type, 'Origins of Modernity and the Late Nineteenth-Century Break', 'Students begin by understanding why modern art emerged: industrialization, colonial modernity, urban life, photography, and new models of perception reshaped what art could do.', 0),
  ('377b30fc-b151-4583-86a3-5f36e15dea72', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '4eefcc1b-fd75-4b7d-85a3-76234366604a', 'subtopic'::public.curated_course_node_type, 'Modernity, urban life, and new publics', 'Students learn that modern art was not just a style but a response to rapid social change, new cities, new audiences, and new institutions.', 0),
  ('8b547ea3-cd4e-4432-a1e4-9137ab6f78c0', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '377b30fc-b151-4583-86a3-5f36e15dea72', 'concept'::public.curated_course_node_type, 'Industrialization, capitalism, and the modern city', null, 0),
