  ('bee05313-e7a3-4ec8-823d-b902529bb216', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'e01fa6b0-5c07-4220-8f09-b7df6041468d', 'concept'::public.curated_course_node_type, 'Impressionist light, color, and urban modernity', null, 0),
