  ('8f2b13bc-c1b6-484e-bd1e-8d98795a2e46', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'e01fa6b0-5c07-4220-8f09-b7df6041468d', 'concept'::public.curated_course_node_type, 'Early modern experiments in form, color, and subject', null, 2),
  ('37cc1aa9-c0b3-4695-a525-2cc21522d15f', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', null, 'topic'::public.curated_course_node_type, 'Cubism, Abstraction, and the Avant-Garde', 'This section develops the core modernist shift from illusionistic representation toward fragmented form, abstraction, experimentation, and artistic self-consciousness.', 1),
  ('de603223-8257-40ee-9bb9-0a7791348cf9', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '37cc1aa9-c0b3-4695-a525-2cc21522d15f', 'subtopic'::public.curated_course_node_type, 'Cubism and the reconstruction of seeing', 'Cubism teaches students how artists dismantled single-point perspective and rebuilt pictorial space as a conceptual field.', 0),
  ('0a15dfc9-bce1-4a86-bf25-e79e6b5ebb36', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'de603223-8257-40ee-9bb9-0a7791348cf9', 'concept'::public.curated_course_node_type, 'Analytic and Synthetic Cubism', null, 0),
  ('f820e768-d288-47bd-a9a3-68400223da28', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'de603223-8257-40ee-9bb9-0a7791348cf9', 'concept'::public.curated_course_node_type, 'Collage, fragmentation, multiple viewpoints, and simultaneity', null, 1),
  ('f4baca56-27ed-4ee1-ba97-1514c2780770', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'de603223-8257-40ee-9bb9-0a7791348cf9', 'concept'::public.curated_course_node_type, 'Still life, newspaper, typography, and modern materials', null, 2),
  ('ce9fe6df-a484-4902-986b-bb29b746085d', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '37cc1aa9-c0b3-4695-a525-2cc21522d15f', 'subtopic'::public.curated_course_node_type, 'Abstraction and nonobjective art', 'Students learn the difference between abstraction from the visible world and nonobjective art built from color, line, form, and spiritual or formal ideas.', 1),
