  ('5d94b84f-3a6b-4ce3-81cd-52517157f9e9', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'ce9fe6df-a484-4902-986b-bb29b746085d', 'concept'::public.curated_course_node_type, 'Color, geometry, rhythm, and composition', null, 1),
  ('f96cc6a9-71d1-4612-a184-fb9ac3c966cd', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', 'ce9fe6df-a484-4902-986b-bb29b746085d', 'concept'::public.curated_course_node_type, 'Spiritual, utopian, and formalist arguments', null, 2),
