  ('640db2f2-f51d-4faa-a447-d260c4012b2a', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '8a4b3320-cc6e-49df-8e30-e95cdbfa0753', 'concept'::public.curated_course_node_type, 'Originality, shock, and anti-academic positions', null, 1),
  ('bc9749ae-d9b7-4b64-8a58-8878a9a37d25', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '8a4b3320-cc6e-49df-8e30-e95cdbfa0753', 'concept'::public.curated_course_node_type, 'Medium specificity and the modernist canon', null, 2),
  ('7e83695f-13b4-4e34-8a93-ab2d0385444f', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', null, 'topic'::public.curated_course_node_type, 'Dada, Surrealism, and the Critique of Reason', 'Students examine how artists responded to war, trauma, psychoanalysis, chance, and irrationality by attacking conventional art, language, and social order.', 2),
