  ('c3f6d58c-ac3c-4bf9-b57b-5aaa4a7a1f62', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', '714aacc6-cc19-42e1-a8ae-319fd9dfb694', 'concept'::public.curated_course_node_type, 'Revolution, colonialism, gender, and power', null, 2),
  ('e85a7303-75a5-4ca2-a234-538542a0891e', 'f6a7b8c9-0d1e-4f58-9c78-8d9e0f1a2b48', null, 'topic'::public.curated_course_node_type, 'Bauhaus, Constructivism, Design, and Modern Media', 'This topic links art to design, architecture, photography, typography, and political modernism, showing how modern art entered everyday life and mass communication.', 3);
